	/**
	 * Result-local, paired dictionary cache. Probe collisions only drop a retained term. The table starts small and
	 * grows with the number of distinct terms a result turns out to have, so that a term which recurs across a large
	 * result is looked up once instead of once for every row another term displaced it.
	 */
	private static final class DetachedProjection {
		private static final int INITIAL_CAPACITY = 1024;
		private static final int MAX_CAPACITY = 1 << 16;
		private final NativeLmdbQuerySource source;
		private final Object snapshot;
		private final ValueResolutionScope scope;
		private long epoch;
		private long[] ids = new long[INITIAL_CAPACITY];
		private int[] masks = new int[INITIAL_CAPACITY];
		private Value[] values = new Value[INITIAL_CAPACITY];
		private int shift = Long.SIZE - Integer.numberOfTrailingZeros(INITIAL_CAPACITY);
		/** Terms stored since the table was created, cleared or last grown. */
		private int stored;
		private NativeProjectedBindingSet previous;

		DetachedProjection(NativeLmdbQuerySource source, Object snapshot, ValueResolutionScope scope, long epoch) {
			this.source = source;
			this.snapshot = snapshot;
			this.scope = scope;
			this.epoch = epoch;
		}

		boolean matches(NativeLmdbQuerySource source, Object snapshot, ValueResolutionScope scope) {
			return this.source == source && this.snapshot == snapshot && this.scope == scope;
		}

		void clear(long epoch) {
			Arrays.fill(values, null);
			stored = 0;
			previous = null;
			this.epoch = epoch;
		}

		private static int bucket(long id, int mask, int shift) {
			long hash = (id ^ ((long) mask << Integer.SIZE)) * 0x9E3779B97F4A7C15L;
			return (int) (hash >>> shift);
		}

		Value value(long id, int mask) {
			int bucket = bucket(id, mask, shift);
			return ids[bucket] == id && masks[bucket] == mask ? values[bucket] : null;
		}

		void put(long id, int mask, Value value) {
			if (++stored > values.length && values.length < MAX_CAPACITY) {
				grow();
			}
			int bucket = bucket(id, mask, shift);
			ids[bucket] = id;
			masks[bucket] = mask;
			values[bucket] = value;
		}

		private void grow() {
			long[] oldIds = ids;
			int[] oldMasks = masks;
			Value[] oldValues = values;
			int capacity = oldValues.length << 2;
			ids = new long[capacity];
			masks = new int[capacity];
			values = new Value[capacity];
			shift = Long.SIZE - Integer.numberOfTrailingZeros(capacity);
			stored = 1;
			for (int i = 0; i < oldValues.length; i++) {
				Value value = oldValues[i];
				if (value != null) {
					int bucket = bucket(oldIds[i], oldMasks[i], shift);
					ids[bucket] = oldIds[i];
					masks[bucket] = oldMasks[i];
					values[bucket] = value;
				}
			}
		}
	}

